SELECT entry, 10, Method, ZoneOrSort, MinLevel, MaxLevel, QuestLevel, Type, RequiredClasses, RequiredRaces, RequiredSkill, RequiredSkillValue, RequiredCondition, RepObjectiveFaction, RepObjectiveValue, RequiredMinRepFaction, RequiredMinRepValue, RequiredMaxRepFaction, RequiredMaxRepValue, SuggestedPlayers, LimitTime, QuestFlags, SpecialFlags, PrevQuestId, NextQuestId, ExclusiveGroup, BreadcrumbForQuestId, NextQuestInChain, SrcItemId, SrcItemCount, SrcSpell, 'Zenn sitt ærend', 'Ivrig etter arbeid, ser æg.  Dæ æ flaks for dæg, for dæ går ikje ein dag utan at æg skulle ønske æg hadde ein ung $c te å gjera ærenda mine.$b$bSjå, $N, æg kan gjera dæg veldig glad å gi dæg ting du aldri har drøymt om.  Men for at dæ skal skje, må du hente nokre ting te mæg.$b$bForretningane mine i skogen krev ofte visse. . .ingrediensar.  Hent te mæg 3 Nightsaber Fangs, 3 Strigid Owl Feathers å 3 Webwood Spider Silk.$b$bLa oss halde dette hemmeleg mellom oss, $r.', 'Kom med 3 Nightsaber Fangs, 3 Strigid Owl Feathers å 3 Webwood Spider Silk te Zenn Foulhoof utanfor Dolanaar.', 'Ha ha!  Godt gjort, verkeleg.$b$bKven skulle trudd at æg, Zenn Foulhoof, skulle ha ein $r te å gjera ærenda mine?  I alle fall ikje æg!  Men slik æ dæ... denne kjære verda vår æ full av overraskingar.$b$bTre hurra for dei naive å lettlurte!$b$bDæ æ jabnå så dræge.', 'Har du vore ein travel liten bie, $N?  Æg har venta på at du skal kome med dæ æg treng.', EndText, ObjectiveText1, ObjectiveText2, ObjectiveText3, ObjectiveText4, ReqItemId1, ReqItemId2, ReqItemId3, ReqItemId4, ReqItemCount1, ReqItemCount2, ReqItemCount3, ReqItemCount4, ReqSourceId1, ReqSourceId2, ReqSourceId3, ReqSourceId4, ReqSourceCount1, ReqSourceCount2, ReqSourceCount3, ReqSourceCount4, ReqCreatureOrGOId1, ReqCreatureOrGOId2, ReqCreatureOrGOId3, ReqCreatureOrGOId4, ReqCreatureOrGOCount1, ReqCreatureOrGOCount2, ReqCreatureOrGOCount3, ReqCreatureOrGOCount4, ReqSpellCast1, ReqSpellCast2, ReqSpellCast3, ReqSpellCast4, RewChoiceItemId1, RewChoiceItemId2, RewChoiceItemId3, RewChoiceItemId4, RewChoiceItemId5, RewChoiceItemId6, RewChoiceItemCount1, RewChoiceItemCount2, RewChoiceItemCount3, RewChoiceItemCount4, RewChoiceItemCount5, RewChoiceItemCount6, RewItemId1, RewItemId2, RewItemId3, RewItemId4, RewItemCount1, RewItemCount2, RewItemCount3, RewItemCount4, RewRepFaction1, RewRepFaction2, RewRepFaction3, RewRepFaction4, RewRepFaction5, RewRepValue1, RewRepValue2, RewRepValue3, RewRepValue4, RewRepValue5, RewRepSpilloverMask, RewXP, RewOrReqMoney, RewMoneyMaxLevel, RewSpell, RewSpellCast, RewMailTemplateId, RewMailDelaySecs, RewMailMoney, PointMapId, PointX, PointY, PointOpt, DetailsEmote1, DetailsEmote2, DetailsEmote3, DetailsEmote4, DetailsEmoteDelay1, DetailsEmoteDelay2, DetailsEmoteDelay3, DetailsEmoteDelay4, IncompleteEmote, CompleteEmote, OfferRewardEmote1, OfferRewardEmote2, OfferRewardEmote3, OfferRewardEmote4, OfferRewardEmoteDelay1, OfferRewardEmoteDelay2, OfferRewardEmoteDelay3, OfferRewardEmoteDelay4, StartScript, CompleteScript
FROM quest_template WHERE entry = 488 AND patch = 0;

